import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F


def _get_world_size_rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size(), dist.get_rank()
    return 1, 0


class _AllGatherLastDim(torch.autograd.Function):
    """All-gather along the last dimension with a slice-correct backward.

    Every rank receives the full (concatenated) output.  Because the loss is
    replicated on all ranks, the gradient of a rank's local shard is simply the
    corresponding slice of the incoming gradient.
    """

    @staticmethod
    def forward(ctx, tensor):
        world_size, rank = _get_world_size_rank()
        ctx.world_size = world_size
        ctx.rank = rank
        ctx.local_size = tensor.shape[-1]

        if world_size == 1:
            return tensor

        tensor = tensor.contiguous()
        gathered = [torch.empty_like(tensor) for _ in range(world_size)]
        dist.all_gather(gathered, tensor)
        return torch.cat(gathered, dim=-1)

    @staticmethod
    def backward(ctx, grad_output):
        if ctx.world_size == 1:
            return grad_output
        start = ctx.rank * ctx.local_size
        return grad_output.narrow(-1, start, ctx.local_size).contiguous()


class _AllReduceSum(torch.autograd.Function):
    """Sum the tensor across ranks with an identity backward.

    The output is replicated, so each rank's local partial output receives the
    (replicated) gradient unchanged.
    """

    @staticmethod
    def forward(ctx, tensor):
        world_size, _ = _get_world_size_rank()
        if world_size == 1:
            return tensor
        out = tensor.clone()
        dist.all_reduce(out, op=dist.ReduceOp.SUM)
        return out

    @staticmethod
    def backward(ctx, grad_output):
        return grad_output


class ColumnParallelLinear(nn.Module):
    """Linear layer whose output dimension is split across tensor-parallel ranks.

    ``master_weight`` has shape ``(out_features, in_features)``.  Each rank
    keeps ``weight = master_weight[out_start:out_end]`` and the bias (if used)
    is sharded along the output dimension as well.  The forward pass computes
    the local shard and all-gathers the results along the last dimension.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        world_size, rank = _get_world_size_rank()
        weight_shard = torch.tensor_split(master_weight, world_size, dim=0)[rank]
        self.weight = nn.Parameter(weight_shard.detach().clone())

        if bias:
            out_features_per_partition = self.weight.shape[0]
            self.bias = nn.Parameter(
                torch.zeros(
                    out_features_per_partition,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        output = F.linear(x, self.weight, self.bias)
        return _AllGatherLastDim.apply(output)


class RowParallelLinear(nn.Module):
    """Linear layer whose input dimension is split across tensor-parallel ranks.

    ``master_weight`` has shape ``(out_features, in_features)``.  Each rank
    keeps ``weight = master_weight[:, in_start:in_end]`` and the input is
    expected to be sharded along its last dimension.  The partial outputs are
    summed with an all-reduce; the bias is full-sized and added afterwards.
    """

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        world_size, rank = _get_world_size_rank()
        weight_shard = torch.tensor_split(master_weight, world_size, dim=1)[rank]
        self.weight = nn.Parameter(weight_shard.detach().clone())

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        partial_output = F.linear(x, self.weight)
        output = _AllReduceSum.apply(partial_output)
        if self.bias is not None:
            output = output + self.bias
        return output

